import React, { useState, useEffect } from 'react';
import { attendanceService } from '../../services/attendanceService';
import '../../styles/table.scss';

const ExcessiveLeaveAlert = () => {
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchAlerts = async () => {
      try {
        const year = new Date().getFullYear();
        const result = await attendanceService.getExcessiveLeave(year);
        if (result.success) {
          setAlerts(result.data);
        }
      } catch (error) {
        console.error("Failed to fetch leave alerts", error);
      } finally {
        setLoading(false);
      }
    };
    fetchAlerts();
  }, []);

  return (
    <div className="alert-page animate-fade-in" style={{ padding: '2rem' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '1.875rem', fontWeight: 'bold', color: '#1f2937' }}>Cảnh Báo Nghỉ Phép Quá Mức</h1>
        <p style={{ color: '#6b7280' }}>Nhân viên sử dụng nhiều ngày nghỉ hoặc vắng mặt</p>
      </div>

      <div className="modern-table-container">
        {loading ? (
          <div style={{ padding: '2rem', textAlign: 'center' }}>Đang kiểm tra cảnh báo...</div>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Mã NV</th>
                <th>Họ Tên</th>
                <th>Phòng Ban</th>
                <th>Nghỉ phép</th>
                <th>Vắng mặt</th>
                <th>Mức độ</th>
              </tr>
            </thead>
            <tbody>
              {alerts.map((alert) => (
                <tr key={alert.EmployeeID}>
                  <td>EMP-{String(alert.EmployeeID).padStart(5, '0')}</td>
                  <td style={{ fontWeight: '500' }}>{alert.FullName}</td>
                  <td>{alert.DepartmentName}</td>
                  <td><span className="status-badge leave">{alert.TotalLeave} ngày</span></td>
                  <td><span className="status-badge absent">{alert.TotalAbsent} ngày</span></td>
                  <td>
                    <span className={`status-badge ${alert.Severity === 'High' ? 'absent' : 'leave'}`}>
                      {alert.Severity}
                    </span>
                  </td>
                </tr>
              ))}
              {alerts.length === 0 && (
                <tr>
                  <td colSpan="6" style={{ textAlign: 'center', padding: '2rem' }}>Tất cả nhân viên đều trong mức nghỉ phép cho phép</td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default ExcessiveLeaveAlert;
